// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(guess)))));
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance one block so the answer is determined by the locked block.
        vm.roll(block.number + 2);

        uint256 balBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = actor.balance;

        bool paid = balAfter == balBefore + 2 ether;
        bool correctGuess = guess == keccak256(abi.encodePacked(blockhash(block.number - 1)));

        // Reference: payout iff guess matches the answer. Bug: payout iff it does not.
        assertTrue(paid == correctGuess);
    }
}
